const fmt = formatDateTime;
const clean = (v, max=160) => String(v || '').trim().slice(0,max);
const asDataUrl = file => new Promise((resolve,reject) => { const reader=new FileReader(); reader.onerror=()=>reject(new Error('Photo could not be read.')); reader.onload=()=>resolve(reader.result); reader.readAsDataURL(file); });
const withTimeout = (promise, message, ms=12000) => Promise.race([promise, new Promise((_,reject)=>setTimeout(()=>reject(new Error(message)),ms))]);
const cloudinaryName = import.meta.env.VITE_CLOUDINARY_CLOUD_NAME;
const cloudinaryPreset = import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET;
async function uploadStudentPhoto(file) {
  if (!cloudinaryName || !cloudinaryPreset) return asDataUrl(file);
  try {
    const body = new FormData();
    body.append('file', file); body.append('upload_preset', cloudinaryPreset); body.append('folder', 'campuspass/profilePhotos');
    const response = await fetch(`https://api.cloudinary.com/v1_1/${cloudinaryName}/image/upload`, { method:'POST', body });
    const result = await response.json();
    if (!response.ok || !result.secure_url) throw new Error('Cloudinary upload failed.');
    return result.secure_url;
  } catch { return asDataUrl(file); }
}
async function uploadCloudinaryFile(file, folder='campuspass/permissionLetters') {
  if (!cloudinaryName || !cloudinaryPreset) throw new Error('Add the Cloudinary unsigned upload preset to .env before uploading files.');
  const body=new FormData(); body.append('file',file); body.append('upload_preset',cloudinaryPreset); body.append('folder',folder);
  const type=file.type==='application/pdf'?'raw':'image';
  const response=await fetch(`https://api.cloudinary.com/v1_1/${cloudinaryName}/${type}/upload`,{method:'POST',body}); const result=await response.json();
  if(!response.ok||!result.secure_url)throw new Error(result.error?.message||'Cloudinary file upload failed.'); return result.secure_url;
}
function DocumentPreview({url,name}){if(!url)return <div className="attachment missing"><small>Supporting document</small><b>No document attached</b></div>;const image=/\.(png|jpe?g|webp|gif)(\?|$)/i.test(url);return <div className="attachment"><div><small>Supporting document</small><b>{name||'Student attachment'}</b></div>{image&&<a href={url} target="_blank" rel="noreferrer"><img src={url} alt="Student supporting document"/></a>}<a className="secondary attachment-link" href={url} target="_blank" rel="noreferrer">Open / verify document</a></div>}
const friendlyError = error => {
  if (error?.code === 'permission-denied') return 'You do not have permission for this action. Ask an administrator to verify your role.';
  return error?.message || 'Something went wrong. Please try again.';
};

