      const profile={displayName:clean(form.displayName),email:clean(form.email).toLowerCase(),registerNumber,...profileForRole({...form,role},role),photoUrl,role:needsAdmin?ROLES.ADMIN:ROLES.STUDENT,requestedRole:role,active:needsAdmin,approvalStatus:needsAdmin?'APPROVED':'PENDING',disabled:false,deleted:false,createdAt:serverTimestamp()};
