  return <section>{student&&page==='dashboard'&&<StudentHome user={user} records={records}/>}<div className="stat-grid"><Metric label={student?'Total requests':'All requests'} value={records.length} active={view==='all'} onClick={()=>show('all')}/><Metric label={student?'In progress':pending?'Needs your review':'In progress'} value={filterRequests(records,{status:reviewStatus}).length} accent active={view===reviewStatus} onClick={()=>show(reviewStatus)}/><Metric label={student?'Issued passes':'Approved'} value={filterRequests(records,{status:'approved',role:pending?user.role:''}).length} active={view==='approved'} onClick={()=>show('approved')}/><Metric label="Declined" value={filterRequests(records,{status:'rejected',role:pending?user.role:''}).length} active={view==='rejected'} onClick={()=>show('rejected')}/></div>{[ROLES.WARDEN,ROLES.COUNCILLOR].includes(user.role)&&<div className="occupancy"><b>{user.hostel||'Both hostels'}{user.role===ROLES.WARDEN?' · '+(wardenCoverageLabel(user.wardenCoverage).join(', ')||'No years assigned'):''}</b><span>{records.filter(x=>x.status==='CURRENTLY_OUT').length} currently outside</span></div>}{student&&page==='passes'&&records.filter(r=>['APPROVED','CURRENTLY_OUT','CLEARED'].includes(r.status)).map(r=><PassCard key={r.id} record={r}/>)}<RequestTable records={records} role={user.role} user={user} demo={demo} notify={notify} view={view} setView={setView} previewUpdate={previewUpdate}/></section>
