  const list=filterRequests(records,{status:view,hostel,date,category,studentType:studentView?'':studentType,role:QUEUE_FOR_ROLE[role]?role:''}).filter(r=>(!coverage||`${institutionGroup(r.institution)}:${r.year}`===coverage)&&`${r.studentName} ${r.registerNumber} ${r.passNumber}`.toLowerCase().includes(term.toLowerCase())).sort((a,b)=>!studentView&&QUEUE_FOR_ROLE[role]?Number(categoryOf(b)==='EMERGENCY')-Number(categoryOf(a)==='EMERGENCY'):0);
